1039	// decodeHostCLIJSON decodes the FIRST JSON value on the host CLI's stdout and
1040	// ignores whatever follows it.
1041	//
1042	// The host `entire` CLI appends human notices to the SAME stream its --json
1043	// output goes to. Released versions before the update notice moved to stderr
1044	// print "\nUpdate available! x -> y\nRelease notes: ..." from a post-run hook,
1045	// so `entire checkpoint explain --json` emits a complete JSON value and THEN a
1046	// banner. A strict json.Unmarshal over the whole buffer fails that with
1047	// "invalid character 'U' after top-level value" -- and only on a first-ever
1048	// run, because the 24h version-check cache suppresses the banner on the next
1049	// one. That made a deterministic first-run failure look like flakiness: setup
1050	// reported "session export failed" once and then silently healed.
1051	//
1052	// Tolerating trailing bytes is the durable fix: the JSON value is the contract,
1053	// anything after it is chatter this process does not own. Leading garbage stays
1054	// an error, because that would mean the value is not first and no prefix of the
1055	// stream can be trusted.
1056	func decodeHostCLIJSON(data []byte, target any) error {
1057		decoder := json.NewDecoder(bytes.NewReader(data))
1058		if err := decoder.Decode(target); err != nil {
1059			if errors.Is(err, io.EOF) {
1060				// json.Unmarshal's wording for an empty buffer, preserved so callers
1061				// and their tests keep reading one message for one condition.
1062				return errors.New("unexpected end of JSON input")
1063			}
1064			return err
1065		}
1066		return nil
1067	}
